CREATE TABLE IF NOT EXISTS clients (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,lead_id BIGINT UNSIGNED NULL,name VARCHAR(180) NOT NULL,company VARCHAR(180) NULL,email VARCHAR(255) NULL,phone VARCHAR(60) NULL,status ENUM('active','inactive','archived') NOT NULL DEFAULT 'active',public_token CHAR(64) NOT NULL UNIQUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(lead_id),CONSTRAINT fk_client_lead FOREIGN KEY(lead_id) REFERENCES leads(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS client_projects (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,client_id BIGINT UNSIGNED NOT NULL,lead_id BIGINT UNSIGNED NULL,proposal_id BIGINT UNSIGNED NULL,invoice_id BIGINT UNSIGNED NULL,project_number VARCHAR(80) NOT NULL UNIQUE,public_token CHAR(64) NOT NULL UNIQUE,name VARCHAR(255) NOT NULL,description TEXT NULL,service VARCHAR(150) NULL,budget DECIMAL(15,2) NOT NULL DEFAULT 0,amount_paid DECIMAL(15,2) NOT NULL DEFAULT 0,balance_due DECIMAL(15,2) NOT NULL DEFAULT 0,start_date DATE NULL,due_date DATE NULL,completed_at DATETIME NULL,status ENUM('planning','in_progress','on_hold','in_review','completed','cancelled') NOT NULL DEFAULT 'planning',priority ENUM('low','normal','high','urgent') NOT NULL DEFAULT 'normal',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(client_id),INDEX(status),CONSTRAINT fk_project_client FOREIGN KEY(client_id) REFERENCES clients(id) ON DELETE CASCADE,CONSTRAINT fk_project_lead FOREIGN KEY(lead_id) REFERENCES leads(id) ON DELETE SET NULL,CONSTRAINT fk_project_proposal FOREIGN KEY(proposal_id) REFERENCES proposals(id) ON DELETE SET NULL,CONSTRAINT fk_project_invoice FOREIGN KEY(invoice_id) REFERENCES invoices(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS project_status_history (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,project_id BIGINT UNSIGNED NOT NULL,old_status VARCHAR(40) NULL,new_status VARCHAR(40) NOT NULL,notes TEXT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(project_id),CONSTRAINT fk_status_project FOREIGN KEY(project_id) REFERENCES client_projects(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
